pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        address initialOwner = address(0xBEEF);
        vm.prank(address(this));
        address current = c.owner();
        if (current == address(0)) {
            vm.prank(current);
            try c.transferOwnership(initialOwner) {
            } catch {
            }
        } else if (current != initialOwner) {
            vm.prank(current);
            try c.transferOwnership(initialOwner) {
            } catch {
            }
        }

        address ownerBefore = c.owner();
        vm.assume(caller != ownerBefore);

        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == ownerBefore);
    }
}
